<div class="page-head"><div><p class="eyebrow">Sales Management</p><h1>Sales Returns</h1><p>Process returned sold items and automatically add them back to stock.</p></div></div>
<section class="panel"><div class="panel-head"><div><h2>Process Sales Return</h2><span class="panel-sub">Return quantity cannot exceed the original sale.</span></div></div>
<form method="post" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field full"><label>Completed Sale</label><select name="sale_id" required><option value="">— Select sale —</option><?php foreach($sales as $s): ?><option value="<?=$s['id']?>">Sale #<?=$s['id']?> — <?=e($s['product'])?> (<?=e($s['sku'])?>) — Qty <?=e($s['quantity'])?> — ৳<?=number_format((float)$s['unit_price'],2)?>/unit — <?=e(date('d M Y',strtotime($s['created_at'])))?></option><?php endforeach; ?></select></div><div class="field"><label>Return Quantity</label><input type="number" name="quantity" min="1" required></div><div class="field"><label>Reason</label><input type="text" name="reason" maxlength="255" placeholder="Damaged, wrong item, customer request..." ></div></div><div class="form-actions"><button class="btn role-btn">↩ Process Sales Return</button></div></form></section>
<br><section class="panel"><div class="panel-head"><div><h2>Sales Return History</h2><span class="panel-sub">Returned quantities are included in stock movement.</span></div></div><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Sale</th><th>Product</th><th>Qty</th><th>Refund Value</th><th>Reason</th><th>By</th></tr><?php foreach($returns as $r): ?><tr><td><?=e(date('d M Y, h:i A',strtotime($r['created_at'])))?></td><td>#<?=e($r['sale_id'])?></td><td><b><?=e($r['product'])?></b><br><small><?=e($r['sku'])?></small></td><td><?=e($r['quantity'])?></td><td>৳<?=number_format((float)$r['refund_amount'],2)?></td><td><?=e($r['reason']??'—')?></td><td><?=e($r['user_name']??'—')?></td></tr><?php endforeach; ?><?php if(!$returns): ?><tr><td colspan="7" class="empty">No sales returns yet.</td></tr><?php endif; ?></table></div></section><?php require __DIR__.'/../../../includes/role_footer.php'; ?>
